"""Build the dated feasibility report from verified saved records."""
from pathlib import Path
import json,html,re
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
for label,suffix in [('Helvetica','Regular'),('Helvetica-Bold','Bold'),('Helvetica-Oblique','Italic'),('Helvetica-BoldOblique','BoldItalic')]:
    pdfmetrics.registerFont(TTFont(label,'/usr/share/fonts/liberation/LiberationSans-'+suffix+'.ttf'))
P=Path(__file__).resolve().parents[1];R=P/'04-Results';Q=R/'qualification';out=P/'01-Papers';out.mkdir(exist_ok=True)
def read(name):return json.loads((Q/name).read_text())
r=read('qualification.json');v=read('numerical-verification.json');ind=read('independent-metrics.json');replay=read('clean-replay.json');cost=json.loads((R/'cost-projection.json').read_text());t4=next(x for x in r['rows'] if x['cell_type']=='T4c')
assert all(x['status']=='pass' for x in [r,v,ind,replay]),'Report requires passing qualification records'
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='TitleAI',fontName='Helvetica-Bold',fontSize=25,leading=29,textColor=colors.HexColor('#143b49'),spaceAfter=17));styles.add(ParagraphStyle(name='DeckAI',fontSize=12,leading=17,textColor=colors.HexColor('#52656b'),spaceAfter=14));styles.add(ParagraphStyle(name='BodyAI',fontSize=10,leading=14,spaceAfter=9));styles.add(ParagraphStyle(name='SmallAI',fontSize=8,leading=10.5,spaceAfter=7));styles['Heading2'].textColor=colors.HexColor('#24738a');styles['Heading2'].spaceAfter=9
story=[];md=[]
def title(s):story.append(Paragraph(s,styles['TitleAI']));md.append('# '+s+'\n')
def h(s):story.append(Paragraph(s,styles['Heading2']));md.append('## '+s+'\n')
def para(s,small=False):story.append(Paragraph(s,styles['SmallAI' if small else 'BodyAI']));md.append(re.sub('<[^>]+>','',re.sub(r'<link href="([^"]+)"[^>]*>(.*?)</link>',r'[\2](\1)',s).replace('<br/>','\n').replace('<b>','**').replace('</b>','**'))+'\n')
def table(headers,rows,widths):
 data=[[Paragraph(html.escape(str(x)),styles['SmallAI']) for x in row] for row in [headers]+rows];t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e7f0f3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.6,colors.HexColor('#9eb4bd')),('LINEBELOW',(0,1),(-1,-1),.25,colors.HexColor('#dce4e7')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.append(t);story.append(Spacer(1,10));md.append('| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)+'\n')
def fig(name,caption):story.append(Image(str(R/'figures'/name),width=492,height=162.36));para(caption,True);md.append('![Figure](../04-Results/figures/'+name+')\n')
def page():story.append(PageBreak());md.append('\n---\n')
def link(label,url):return f'<link href="{url}" color="#24738a">{label}</link>'

title('AI-06 | Biological references for interpretability')
para('Qualification and feasibility report<br/>2 October 2026 | AI interpretability portfolio',False)
h('What is complete')
para('The project, isolated CPU environments, verified public model downloads, literature audit, biological evidence table, native tutorial reproduction and bounded numerical checks are complete. This report documents a successful software qualification and the practical cost of the proposed study.')
para('<b>The comparative interpretability study is not completed.</b> No method winner, exhaustive causal-effect map, biological agreement score, interaction finding or ensemble conclusion is claimed. The full comparative protocol remains an unfrozen draft.')
table(['Qualification','Observed','Predeclared target'],[['T4c ON direction selectivity',f"{t4['dsi']:.6f}",'0.63 +/- 0.02'],['T4c preferred direction',f"{t4['pd_degrees']:.6f} degrees",'56.24 +/- 2 degrees'],['Final guarded qualification','129.60 s; 2.02 GiB peak RSS','One CPU worker; <=2 numeric threads'],['Fresh environment replay','Bitwise equal selected trace','Same machine; independently installed environment']],[188,144,160])
h('Placement and research decision')
para('AI-06 belongs under AI interpretability because the object being evaluated is the analysis method. Fly neuroscience provides the model and condition-specific reference observations. Existing AI and CN projects, shared indexes and their environments were not modified.')
para('The literature gate is <b>NARROW</b>. Prior biological benchmarks and flyvis silencing work exist. The candidate contribution is the particular comparison of method predictions with a declared model-intervention reference, with biological agreement assessed separately.')
para('AI assistance produced the source review, implementation, checks and this report. Local verification is not external scientific review. One development model was examined; no ensemble uncertainty interval is justified.',True)
page()

title('1 | Reproducing the released model')
para('Software: Python 3.12.14, FlyVis 1.2.0 (source commit g92b3845cc), CPU PyTorch 2.5.1 and NumPy 1.26.4. Model flow/0000/000 is the named tutorial model; it was chosen before simulation. Both released archives matched official SHA-256 values. No training or weight fitting was performed.')
para('The constructed network contains 45,669 nodes, 1,513,231 spatial edges, 65 model compartments and 604 realized type-pair connections. CT1 has two compartments, reconciling 65 model types with 64 biological types. A Lawf1 self-pair exists in the JSON but instantiates no spatial edge. The network reports 734 free parameters.')
para('Stimuli followed the '+link('official moving-edge tutorial','https://turagalab.github.io/flyvis/examples/04_flyvision_moving_edge_responses/')+': 12 angles at 30-degree spacing, ON and OFF edges, speed parameter 19 (=110.2 degrees/s), offsets [-10,11], 5 ms integration, one-second pre/post periods plus the native extra one-second grey adaptation. Batch size was one; central cells were read out.')
fig('tuning.png','Figure 1. Descriptive responses from one development model and one speed. No error bars: repeated deterministic simulations are not independent models. T4 uses ON, T5 uses OFF. The weak T4d DSI illustrates why matching one tutorial target does not certify all cells or an ensemble.')
para('The native DSI uses rectified raw-voltage peaks within the moving-edge window. For each polarity, its numerator is the magnitude of the circular sum over angles; its denominator is the larger total peak response over ON/OFF. No baseline subtraction is used. This differs from the common preferred-minus-null contrast index.')
para('T4c target errors were 0.00263848 DSI and 0.00420673 degrees. Reproduction is a software check. Its roughly 56-degree preferred direction is not evidence of perfect biological matching; no matched biological intervention was scored here.',True)
page()

title('2 | Numerical verification and resources')
fig('verification-and-memory.png','Figure 2. Left: one predeclared ON/60-degree trial; half-step values are aligned at coarse-frame endpoints. Right: memory at different interrupted/completed stages, not a controlled performance comparison. Attempt 1 high-water memory was observed after monitoring began.')
table(['Check and scope','Result'],[['Renderer: original-native small eye','Geometry/counts exact; mean differences <=1.12e-16'],['Renderer: 721-receptor central-edge fixture','Four frames agree within 2.23e-16; not bitwise'],['Native vs streaming, full selected trial','Maximum absolute difference 0'],['Identity output gate; locality/restoration','Passed on short Mi1 output-gate control'],['Deterministic repeat; clean environment','Bitwise equal selected full trace'],['Independent NumPy metric recomputation',f"Max DSI error {ind['max_dsi_error']:.3g}; finite and peak checks passed"],['Float64 diagnostic',f"Normalized maximum change {v['float64_normalized_max_error']:.3g}"],['Half-step diagnostic',f"Normalized maximum change {v['half_step_normalized_max_error']:.5f}; threshold 0.05"]],[257,235])
para('Native rendering first exceeded the adopted 4 GiB worker limit (7.29 GiB high-water RSS) and was stopped. A dense receptor-chunk version stayed below 1 GiB but took about 45 s per angle/polarity group; it was stopped to implement sparse pixel membership. The final renderer retains pixel resolution, rasterization, membership and counts while avoiding zero-weight pixels. Summation order can change; equality was tested, not assumed.',True)
para('The full native allocation could not be compared at full size within the memory bound; renderer validation is layered through small-native and full-grid dense-chunk comparisons. Precision/step diagnostics cover one input and central outputs, not all interventions. Minimum time constant was 19.43 ms; none was below 5 ms. No GPU was used.',True)
page()

title('3 | What the source audit changed')
para('Twenty bounded literature queries identified close comparators. This was not a systematic review or complete citation-graph search. No exact matching two-reference benchmark was located; that is not evidence of absence.')
table(['Premise or comparator','Finding and implication'],[['Prior flyvis silencing','The main paper emphasizes currents and modelling-assumption ablations. An indexed author reproduction of its peer-review response reports Mi1/Tm3/Mi4/Mi9 input clamps. The native publisher peer-review PDF was not retrieved. Do not claim first silencing.'],['2026 flyvis scale benchmark','Dhiman and Panwar test frozen flyvis, T4/T5 silencing, and fixed versus refitted decoders. Anatomy plus interventions alone is not new.'],['Existing biological/non-Tracr benchmarks','InterpBench, MIB and subsequent causal-abstraction work have distinct assumptions. The benchmark landscape cannot be described as only near-linear Tracr systems.'],['Piecewise affine and interactions','F(x,y)=max(0,x+y-1) has finite binary interaction 1. Local zero Hessians do not imply zero finite joint effects across activation boundaries. FlyVis also has piecewise-affine fixed-weight dynamics.'],['Model reference versus biology','Single cells/edges plus selected pairs are exhaustive only over declared interventions and stimuli. They are not the unique complete causal structure. Biological knowledge also helped construct the model.']],[162,330])
para('Relevant primary sources: '+link('Lappalainen et al. 2024','https://doi.org/10.1038/s41586-024-07939-3')+'; '+link('Dhiman and Panwar 2026','https://doi.org/10.1007/s12021-026-09811-3')+'; '+link('MIB','https://arxiv.org/abs/2504.13151')+'; '+link('Méloux et al. 2026'.replace('é','e'),'https://arxiv.org/abs/2607.00267')+'. Full query records, source status and unresolved leads are in 01-Papers/literature-search.json and 05-Notes/GAP-MEMO.md.',True)
h('Internal transfer')
para('AI-05 motivates falsification controls, but its current result does not establish that joint tests outperform equally resourced broader singles. AI-03 cautions against conflating mean donors with individual donors; AI-01 cautions that output repair alone need not establish donor-like computation. These are design lessons, not evidence of success in this new system.')
page()

title('4 | Biological evidence stays conditional')
para('The evidence register contains nine biological/structural rows and three explicitly model-only comparators. Retrieved source files, hashes, figure locators and condition details are preserved. Confidence labels apply to each stated experiment, not universal necessity claims.')
table(['Claim','Verified boundary for later scoring'],[['Mi1 and Tm3: Ammer 2015','Explicit slow/fast ON-edge comparison: 12.5 versus 300 degrees/s. Kir2.1 perturbation; downstream HS/VS voltage. Mi1 was required across tested conditions; Tm3 had a speed-dependent requirement in this assay. Direct T4 voltage is a different readout.'],['T5 inputs: Serbe 2016','Tm1/Tm2/Tm4/Tm9 contribute unequally. Complete redundancy is rejected; partially overlapping contributions are supported. Pair blocks used one-copy shibire, so compare to matching one-copy singles, not stronger two-copy singles.'],['Suppression: Gruntman 2018','Voltage results support spatially offset delayed inhibition and null-direction suppression under stated stimuli. Voltage/calcium transformations and stimulus conditions prevent a universal absence-of-enhancement label.'],['Anatomical connectivity','Contacts and synapse counts can check structure or form a baseline. They do not establish functional necessity, delay or causal importance.'],['FlyVis Mi4/CT1/Tm9 mechanisms','These are model hypotheses/comparators, excluded from independent biological correctness labels.']],[153,339])
para('Primary references: '+link('Ammer et al. 2015','https://doi.org/10.1016/j.cub.2015.07.014')+'; '+link('Serbe et al. 2016','https://doi.org/10.1016/j.neuron.2016.01.006')+'; '+link('Gruntman et al. 2018','https://doi.org/10.1038/s41593-017-0046-4')+'; '+link('Shinomiya et al. 2019','https://doi.org/10.7554/eLife.40025')+'. Detailed extraction: 03-Data/biology-key.csv and 05-Notes/BIOLOGY-ANSWER-KEY.md.',True)
h('What remains unanswered')
para('The pilot used 110.2 degrees/s and no scored biological intervention. It therefore does not test the Mi1/Tm3 slow/fast finding or the T5 combinatorial result. Method failures, model-biology gaps, redundancy, compensation and ensemble non-identifiability cannot be diagnosed from this reproduction alone.')
page()

title('5 | Feasibility decision and handoff')
para('A fresh selected trajectory took 2.51 and 2.69 s in the primary environment, and 3.28 s in the clean replay. Grey adaptation added about 0.98-1.34 s. The actual draft reference with four models, 48 stimuli, two strengths, 65 model compartments, 604 realized edges and eight pairs requires <b>260,160 trajectories</b>.')
para(f"Naive single-worker scaling gives <b>{min(cost['projected_exact_wall_hours']):.1f}-{max(cost['projected_exact_wall_hours']):.1f} wall-clock hours ({min(cost['projected_exact_wall_days']):.2f}-{max(cost['projected_exact_wall_days']):.2f} days)</b> excluding grey adaptation/setup and before gradients, decoder tests, naturalistic inputs and verification. This scenario assumes the measured trajectory cost across all trials; slower stimuli and different interventions can change it. The range is not a confidence interval. GPU/optimized-solver cost was not measured.")
para('<b>Decision:</b> close this bounded execution with a verified qualification/feasibility package. Leave the full comparative study explicitly pending and its protocol unfrozen. This is a scope/resource decision; the model competence gate passed. It is not proof that the research is infeasible. No background job, publication or shared-index update is left running.')
table(['Question','Current answer / evidence'],[['Which methods recover model effects?','Unanswered. Exact streaming/output-gate infrastructure passed controls; gradient/patching/circuit-discovery evaluation remains unimplemented/unrun.'],['Does the model match fly biology?','Not scored. Condition-specific literature register exists; one software response was reproduced.'],['Do joint interactions matter?','Not measured here. Piecewise affine does not imply their absence; no Tracr comparison was run.'],['Is connectome-only prediction as good?','Not compared. Structural baselines remain in the draft.'],['What can be reproduced now?','Tutorial qualification, saved numerical checks, selected clean replay and independent aggregation. See REPRODUCTION.md.']],[171,321])
para('Evidence map: qualification/qualification.json and tuning.csv support the reproduced response; numerical-verification.json, streaming-validation.json, independent-metrics.json and clean-replay.json support bounded checks; cost-projection.json supports only the arithmetic scenario. The literature query log and biology-key.csv support the source audit. Failed attempts and frozen protocols are retained in Study History.',True)
para('Limitations: one development model, one speed, synthetic edges, central readouts and no model-level uncertainty; no held-out models, decoder/Sintel experiment, biological agreement score or method ranking. Source code is MIT; a separate pretrained-weight license was not verified. Locked dependencies and source/data manifests are preserved. Report source and an HTML handoff accompany this PDF.',True)

